SCHEMA_CLAIM_TYPES: Tuple[str, ...] = (
    "string",
    "number",
    "integer",
    "boolean",
    "object",
    "array",
)

# verify 时签名合法但模式约束校验失败的固定原因。
SCHEMA_VALIDATION_FAILED_REASON = "schema validation failed"

# verify-with-schema 请求结构或模式参数非法的固定原因。
SCHEMA_VERIFY_INVALID_REQUEST_REASON = "请求参数无效"
# verify-with-schema 按请求模式参数在本租户查不到模式的固定原因。
SCHEMA_VERIFY_SCHEMA_NOT_FOUND_REASON = "凭证模式不存在"
# verify-with-schema 正文模式绑定与请求参数/模式摘要不一致的固定原因。
SCHEMA_VERIFY_BINDING_MISMATCH_REASON = "凭证模式绑定不一致"

# 模式指针在 claims 中未命中的内部哨兵（不得对外暴露）。
_SCHEMA_POINTER_MISSING = object()


def schema_canonical_bytes(payload: Dict[str, Any]) -> bytes:
    """模式注册内容的规范化 JSON（递归键升序、紧凑、UTF-8）。"""
    return crypto.canonicalize(payload)


def schema_content_digest(payload: Dict[str, Any]) -> str:
    """模式注册内容规范化 JSON 的 SHA-256 小写十六进制。"""
    return hashlib.sha256(schema_canonical_bytes(payload)).hexdigest()


def _schema_resolve_pointer(
    claims: Any, tokens: Tuple[str, ...]
) -> Any:
    """按 RFC6901 在 claims 中导航；对象按键、数组按十进制索引。

    未命中（键不存在、数组越界、"-" 末尾指针、经过非容器叶子）返回
    _SCHEMA_POINTER_MISSING。
    """
    current: Any = claims
    for token in tokens:
        if isinstance(current, list):
            if not _JSON_POINTER_ARRAY_INDEX_RE.fullmatch(token):
                return _SCHEMA_POINTER_MISSING
            index = int(token)
            if index >= len(current):
                return _SCHEMA_POINTER_MISSING
            current = current[index]
        elif isinstance(current, dict):
            if token not in current:
                return _SCHEMA_POINTER_MISSING
            current = current[token]
        else:
            return _SCHEMA_POINTER_MISSING
    return current


def _value_matches_schema_type(value: Any, declared: str) -> bool:
    """值是否匹配声明的 JSON 类型（bool 不计入 number/integer）。"""
    if declared == "string":
        return isinstance(value, str)
    if declared == "number":
        return _is_number(value)
    if declared == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if declared == "boolean":
        return isinstance(value, bool)
    if declared == "object":
        return isinstance(value, dict)
    if declared == "array":
        return isinstance(value, list)
    return False


def _validate_claims_against_schema(
    claims: Any, claim_types: Dict[str, str], required_claims: List[str]
) -> None:
    """按模式校验 claims：必填路径必须命中；已命中的声明路径类型须正确。

    声明但非必填、且 claims 中缺失的路径视为可选，不判失败。
    """
    if not isinstance(claims, dict):
        raise ValidationError("claims 必须为 JSON 对象")
    parsed_required = {pointer: _parse_pointer(pointer, "required_claims")
                       for pointer in required_claims}
    for pointer in required_claims:
        value = _schema_resolve_pointer(claims, parsed_required[pointer])
        if value is _SCHEMA_POINTER_MISSING:
            raise ValidationError(
                f"claims 缺少必填路径: {pointer!r}"
            )
    for pointer, declared in claim_types.items():
        tokens = _parse_pointer(pointer, "claim_types")
        value = _schema_resolve_pointer(claims, tokens)
        if value is _SCHEMA_POINTER_MISSING:
            continue
        if not _value_matches_schema_type(value, declared):
            raise ValidationError(
                f"claims 路径 {pointer!r} 的值类型不是声明的 {declared}"
            )


def _validate_schema_payload(
    schema_id: Any,
    version: Any,
    issuer_did: Any,
    claim_types: Any,
    required_claims: Any,
) -> Tuple[str, int, str, Dict[str, str], List[str]]:
    """校验模式注册请求内容；全部非法情形抛 ValidationError。"""
    if not isinstance(schema_id, str) or not SCHEMA_ID_RE.fullmatch(schema_id):
        raise ValidationError(
            "字段 schema_id 必须为以小写字母开头、仅含小写字母/数字/"
            "下划线/连字符且长度 1..64 的字符串"
        )
    if isinstance(version, bool) or not isinstance(version, int) or version < 1:
        raise ValidationError("字段 version 必须为正整数")
    if not isinstance(issuer_did, str) or not issuer_did:
        raise ValidationError("字段 issuer_did 必须为非空字符串")
    if not isinstance(claim_types, dict) or not (
        1 <= len(claim_types) <= 100
    ):
        raise ValidationError(
            "字段 claim_types 必须为含 1..100 个路径映射的 JSON 对象"
        )
    normalized_types: Dict[str, str] = {}
    for pointer, declared in claim_types.items():
        if not isinstance(pointer, str):
            raise ValidationError("claim_types 路径必须为字符串")
        # 仅做 RFC6901 语法校验（以 / 开头、转义合法）；数组索引路径
        # 在模式中允许，签发时按 claims 实际结构导航。
        tokens = _parse_pointer(pointer, "claim_types")
        if not tokens:
            raise ValidationError(
                "claim_types 不允许根路径（空指针）"
            )
        if not isinstance(declared, str) or declared not in SCHEMA_CLAIM_TYPES:
            raise ValidationError(
                "claim_types 路径类型必须为 string/number/integer/"
                "boolean/object/array 之一"
            )
        normalized_types[pointer] = declared
    if not isinstance(required_claims, list):
        raise ValidationError("字段 required_claims 必须为数组")
    seen: set = set()
    normalized_required: List[str] = []
    for pointer in required_claims:
        if not isinstance(pointer, str) or not pointer:
            raise ValidationError(
                "required_claims 元素必须为非空 RFC6901 路径字符串"
            )
        if pointer in seen:
            raise ValidationError(f"required_claims 路径重复: {pointer!r}")
        if pointer not in normalized_types:
            raise ValidationError(
                f"required_claims 路径必须是 claim_types 的键: {pointer!r}"
            )
        seen.add(pointer)
        normalized_required.append(pointer)
    return (
        schema_id, version, issuer_did,
        normalized_types, normalized_required,
    )


def _schema_row_record(row: Dict[str, Any]) -> CredentialSchemaRecord:
    return CredentialSchemaRecord(
        schema_id=row["schema_id"],
        version=int(row["version"]),
        issuer_did=row["issuer_did"],
        claim_types=dict(row["claim_types"]),
        required_claims=list(row["required_claims"]),
        digest=row["digest"],
    )


def _schema_payload_dict(
    schema_id: str,
    version: int,
    issuer_did: str,
    claim_types: Dict[str, str],
    required_claims: List[str],
) -> Dict[str, Any]:
    """参与摘要/幂等判定的规范化模式内容（固定五字段）。"""
    return {
        "schema_id": schema_id,
        "version": version,
        "issuer_did": issuer_did,
        "claim_types": claim_types,
        "required_claims": required_claims,
    }



def _json_equal(left: Any, right: Any) -> bool:
    """JSON 精确相等：布尔与数字不互通，容器递归比较。"""
    if isinstance(left, bool) or isinstance(right, bool):
        return (
            isinstance(left, bool)
            and isinstance(right, bool)
            and left == right
        )
    if _is_number(left) and _is_number(right):
        return left == right
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(
            _json_equal(left[key], right[key]) for key in left
        )
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _json_equal(a, b) for a, b in zip(left, right)
        )
    return left == right


def _validate_predicates(
    claims: Dict[str, Any], predicates: Any
) -> List[Dict[str, Any]]:
    """校验 predicates 列表并返回原样谓词项列表。

    - predicates 必须为非空数组；元素为恰含 path/op[, value] 的对象；
    - op 仅支持 exists/eq/gte/lte；exists 禁止 value，其余必须有 value；
    - path 为相对 claims 的 RFC6901 指针：禁根、禁数组索引、禁越界，
      不得重复、不得存在祖先/后代重叠；
    - gte/lte 要求谓词 value 与 claims 命中值均为非布尔数字。
    """
    if not isinstance(predicates, list) or not predicates:
        raise ValidationError("字段 predicates 必须为非空数组")
    items: List[Dict[str, Any]] = []
    seen_tokens: List[Tuple[str, ...]] = []
    for item in predicates:
        if not isinstance(item, dict):
            raise ValidationError("predicates 元素必须为 JSON 对象")
        if "path" not in item:
            raise ValidationError("predicates 元素缺少字段: path")
        if "op" not in item:
            raise ValidationError("predicates 元素缺少字段: op")
        extra = sorted(set(item) - {"path", "op", "value"})
        if extra:
            raise ValidationError(
                f"predicates 元素含多余字段: {', '.join(extra)}"
            )
        op = item["op"]
        if op not in _PREDICATE_OPS:
            raise ValidationError(
                f"predicates 元素 op 非法: {op!r}"
                "（仅支持 exists/eq/gte/lte）"
            )
        if op == "exists":
            if "value" in item:
                raise ValidationError(
                    "predicates 元素 op 为 exists 时禁止 value 字段"
                )
        elif "value" not in item:
            raise ValidationError(
                f"predicates 元素 op 为 {op} 时缺少字段: value"

def verify_trust_credential_with_schema(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """按调用方指定的模式版本验真外部凭证，返回 (是否有效, 失败原因)。

    校验顺序固定：请求与模式参数 -> 凭证基础字段 -> 模式查找 ->
    模式绑定与 claims -> 锚点 -> 签名格式 -> 密码学验签 -> 有效期 ->
    外部签发 DID 停用通告。
    - 请求体须恰含 body（对象）、signature（非空字符串）、schema_id
      （非空字符串）、schema_version（非布尔正整数）；缺失、多余、
      非对象或类型错误统一返回“请求参数无效”；
    - 凭证基础字段校验与 /v1/trust/credentials/verify 完全一致
      （credential_id/issuer_did/subject_did/claims/issued_at 必填，
      issuer_key_version 可省略，省略按版本 1 且不注入签名正文）；
    - 模式按本租户 (body.issuer_did, schema_id, schema_version) 查找，
      缺失（含他租户同名模式）返回“凭证模式不存在”；
    - body 须含 schema_id/schema_version/schema_digest 且分别等于
      请求参数与该模式版本的内容摘要，否则“凭证模式绑定不一致”；
      claims 缺必填路径或已声明路径类型不符返回
      “schema validation failed”，未声明的额外 claims 保留；
    - 锚点、签名格式、验签、有效期、外部停用通告的原因与优先级
      沿用 /v1/trust/credentials/verify；
    - 模式版本 deprecated/revoked 不影响验真：历史外部凭证仍按该
      版本原摘要判定，不追溯失效，也不得借用其他版本摘要。
    只读：不登记 DID/凭证，不改模式、锚点、状态、历史或审计，
    绝不向上抛异常。
    """
    # 1. 请求结构与模式参数：任何非法统一“请求参数无效”。
    if not isinstance(data, dict):
        return False, SCHEMA_VERIFY_INVALID_REQUEST_REASON
    if set(data) != {"body", "signature", "schema_id", "schema_version"}:
        return False, SCHEMA_VERIFY_INVALID_REQUEST_REASON
    body = data["body"]
    signature = data["signature"]
    schema_id = data["schema_id"]
    schema_version = data["schema_version"]
    if not isinstance(body, dict):
        return False, SCHEMA_VERIFY_INVALID_REQUEST_REASON
    if not isinstance(signature, str) or not signature:
        return False, SCHEMA_VERIFY_INVALID_REQUEST_REASON
    if not isinstance(schema_id, str) or not schema_id:
        return False, SCHEMA_VERIFY_INVALID_REQUEST_REASON
    if (
        not isinstance(schema_version, int)
        or isinstance(schema_version, bool)
        or schema_version < 1
    ):
        return False, SCHEMA_VERIFY_INVALID_REQUEST_REASON

    # 2. 凭证基础字段：与 /v1/trust/credentials/verify 相同分类原因。
    required_str = (
        "credential_id",
        "issuer_did",
        "subject_did",
        "issued_at",
    )
    for field in required_str:
        if field not in body:
            return False, f"凭证缺少字段: {field}"
        value = body[field]
        if not isinstance(value, str) or not value:
            return False, f"凭证字段 {field} 必须为非空字符串"
    if "claims" not in body:
        return False, "凭证缺少字段: claims"
    if not isinstance(body["claims"], dict):
        return False, "凭证字段 claims 必须为 JSON 对象"
    key_version = 1
    if "issuer_key_version" in body:
        version_obj = body["issuer_key_version"]
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj < 1
        ):
            return False, "凭证字段 issuer_key_version 必须为正整数"
        key_version = version_obj
    issuer_did = body["issuer_did"]

    # 3/5. 锁内一次取出模式行与锚点行，判定顺序不变：模式查找 ->
    # 模式绑定与 claims -> 锚点。
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        schema_row = self._get_credential_schema_row_locked(
            bucket, issuer_did, schema_id, schema_version
        )
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None else None
        )
        row = (
            anchors.get(str(key_version))
            if anchors is not None else None
        )
        public_pem = row.get("public_key", "") if row is not None else ""
        status = row.get("status", "active") if row is not None else None
        uses = row.get("uses") if row is not None else None

    # 3. 模式查找：限本租户、同 issuer_did；跨租户同名按不存在。
    if schema_row is None:
        return False, SCHEMA_VERIFY_SCHEMA_NOT_FOUND_REASON

    # 4. 模式绑定与 claims：body 三字段缺一不可，且须分别等于请求
    # 参数与该版本模式的内容摘要（布尔不等于整数，其他版本摘要不可
    # 借用）；claims 校验失败固定 “schema validation failed”。
    body_schema_version = body.get("schema_version")
    if (
        body.get("schema_id") != schema_id
        or not isinstance(body_schema_version, int)
        or isinstance(body_schema_version, bool)
        or body_schema_version != schema_version
        or body.get("schema_digest") != schema_row["digest"]
    ):
        return False, SCHEMA_VERIFY_BINDING_MISMATCH_REASON
    try:
        _validate_claims_against_schema(
            body["claims"],
            schema_row["claim_types"],
            schema_row["required_claims"],
        )
    except ValidationError:
        return False, SCHEMA_VALIDATION_FAILED_REASON

    # 5. 锚点：本租户 (issuer_did, 版本)，仅 active 的 P-256 公钥
    if row is None:
        return False, (
            f"锚点不存在: {issuer_did}#{key_version}"
        )
    if status == "revoked":
        return False, f"锚点已吊销: {issuer_did}#{key_version}"
    # 用途白名单：active 锚点无 vc 用途时按锚点不可用处理
    if uses is not None and "vc" not in uses:
        return False, (
            f"锚点不存在: {issuer_did}#{key_version}"
        )
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, (
            f"锚点公钥不可用: {issuer_did}#{key_version} 不是合法 P-256 公钥"
        )

    # 6/7. 签名格式与密码学验签：签名覆盖完整 body 的规范化 JSON。
    # 省略 issuer_key_version 时不得向签名正文注入该字段。
    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，凭证正文或签名可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "签名校验失败: 验签过程发生内部错误"

    # 8. 有效期：仅在请求 body 提供 expires_at 时检查（缺失保持兼容，
    # 无期限）。须为 UTC 秒精度 Z 格式；当前时间 >= expires_at 判
    # 到期。只读，不写任何状态、不记审计。
    if "expires_at" in body:
        expires_value = body["expires_at"]
        if (
            not isinstance(expires_value, str)
            or not _UTC_Z_SHAPE_RE.match(expires_value)
        ):
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        try:
            expires_dt = _parse_utc_z(expires_value)
        except ValueError:
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        if datetime.now(timezone.utc) >= expires_dt:
            return False, CREDENTIAL_EXPIRED_REASON

    # 9. 原验真成功后查本租户 issuer_did 外部停用通告：命中返回
    #    “外部签发DID已停用：<reason>”；无通告或仅他租户有通告维持
    #    原结论。只读，不写状态、不记审计。
    deactivation_reason = self._external_did_deactivation_reason(
        tenant_id, issuer_did, EXTERNAL_ISSUER_DID_DEACTIVATED_REASON_PREFIX
    )
    if deactivation_reason is not None:
        return False, deactivation_reason
    return True, ""

def _synced_anchor_events_latest(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
) -> Dict[Tuple[str, int], Dict[str, Any]]:
    """读取该来源 cursor<=at 的已同步锚点事件末项视图（只读）。

    该签名方在本租户无同步检查点（含跨租户）抛 NotFoundError；at
    超过检查点抛 ConflictError。返回 (did, key_version) -> 最后
    事件的映射，供单条与批量同步锚点验真共用同一快照。
    """
    with self._lock:
        return self._synced_anchor_events_latest_locked(
            tenant_id, signer_did, at
        )

def _synced_anchor_events_latest_locked(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
) -> Dict[Tuple[str, int], Dict[str, Any]]:
    """``_synced_anchor_events_latest`` 的锁内核心（调用方须持锁）。

    检查点语义与异常同上；返回的末事件视图引用锁内状态，调用方
    须在释放锁前完成使用或复制。
    """
    checkpoints = self._anchor_changes_sync_checkpoints.get(tenant_id)
    cp = checkpoints.get(signer_did) if checkpoints is not None else None
    if cp is None:
        raise NotFoundError("该签名方尚未同步锚点变更")
    checkpoint = int(cp["next_after"])
    if at > checkpoint:
        raise ConflictError("查询时间点超过同步检查点")
    bucket = self._bucket_locked(tenant_id)
    pages: List[Dict[str, Any]] = []
    if bucket is not None:
        pages = bucket.get("synced_anchor_change_pages", {}).get(
            signer_did, []
        )
    latest: Dict[Tuple[str, int], Dict[str, Any]] = {}
    for page in pages:
        for event in page["events"]:
            cursor = int(event["cursor"])
            if cursor > at:
                continue
            key = (event["did"], int(event["key_version"]))
            existing = latest.get(key)
            if existing is None or cursor > int(existing["cursor"]):
                latest[key] = event
    return latest

@staticmethod
def _verify_synced_credential_against(
    latest: Dict[Tuple[str, int], Dict[str, Any]],
    body: Any,
    signature: Any,
) -> Tuple[bool, str]:
    """在已解析的同步锚点快照上验真一条外部凭证（只读）。

    假定 body 为 JSON 对象、signature 为非空字符串；凭证字段、
    锚点、签名格式、验签与有效期规则及原因分类与
    :meth:`verify_trust_credential_synced` 完全一致。
    """
    # 凭证字段（沿用 /v1/trust/credentials/verify 的分类原因）
    required_str = (
        "credential_id",
        "issuer_did",
        "subject_did",
        "issued_at",
    )
    for field in required_str:
        if field not in body:
            return False, f"凭证缺少字段: {field}"
        value = body[field]
        if not isinstance(value, str) or not value:
            return False, f"凭证字段 {field} 必须为非空字符串"
    if "claims" not in body:
        return False, "凭证缺少字段: claims"
    if not isinstance(body["claims"], dict):
        return False, "凭证字段 claims 必须为 JSON 对象"
    key_version = 1
    if "issuer_key_version" in body:
        version_obj = body["issuer_key_version"]
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj < 1
        ):
            return False, "凭证字段 issuer_key_version 必须为正整数"
        key_version = version_obj
    issuer_did = body["issuer_did"]

